<script setup lang="ts">
import AdministratorMfaSetup from '../../../packages/shared/src/AdministratorMfaSetup.vue';import InitialPasswordForm from '../../../packages/shared/src/InitialPasswordForm.vue';import zhCn from 'element-plus/es/locale/lang/zh-cn';import EnvironmentBanner from '../../../packages/shared/src/EnvironmentBanner.vue';
import {ref,onMounted,computed,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useSession} from '../../../packages/shared/src/session';import {useOperations} from '../../../packages/shared/src/operations';import {useTask} from '../../../packages/shared/src/ui';import Status from '../../../packages/shared/src/Status.vue';import {resources} from './resources';
const route=useRoute(),router=useRouter(),session=useSession(),ops=useOperations(),task=useTask(),username=ref(''),password=ref('');onMounted(()=>{if(session.token)void ops.resume();});
const mfaCode=ref(''),showMfaSetup=ref(false);
function mfaCompleted(){showMfaSetup.value=false;mfaCode.value='';task.message.value='验证器已启用，请等待下一枚验证码后登录。';}
const teacherRestricted=computed(()=>session.role===3 && !['/exams','/operations','/teaching'].includes(route.path));
async function login(){const requested=route.fullPath;await session.login(username.value,password.value,true,mfaCode.value||undefined);if(session.initialPasswordRequired)return;password.value='';mfaCode.value='';const allowed=['/teaching','/exams','/operations'].includes(requested.split('?')[0]!);await router.replace(session.role===3&&!allowed?'/exams':requested);void ops.resume();}

function passwordChanged(){session.initialPasswordRequired=false;password.value='';task.error.value='';task.message.value='密码已设置，请使用新密码登录。';}
const groups=[{name:'教学内容',keys:['courses','media','questions']},{name:'用户与权限',keys:['students','staff','roles','privileges']},{name:'营销与交易',keys:['coupons','orders','refunds']},{name:'通知管理',keys:['templates','notices']}];
const pageTitle=computed(()=>resources[route.path.split('/')[1]||'']?.title||({'/':'数据看板','/teaching':'教学学情','/seasons':'赛季与奖励','/exams':'试卷与评分','/reliability':'失败与补偿任务','/operations':'操作记录','/role-permissions':'角色权限绑定','/audit':'管理操作审计','/privacy-requests':'隐私权利申请'}[route.path]||'管理工作台'));
</script>
<template><el-config-provider :locale="zhCn"><div v-if="!session.token || !session.admin" class="admin-login"><div class="card login"><img class="login-brand" src="/brand-logo.png" alt="天机学堂"/><h1>天机学堂管理中心</h1><p class="muted">让教学与管理，更有条理</p><Status :busy="task.busy.value" :error="task.error.value || session.expiredMessage" :message="task.message.value"/><InitialPasswordForm v-if="session.initialPasswordRequired" :username="username" :temporary-password="password" audience="admin" @completed="passwordChanged" @cancel="session.initialPasswordRequired=false;password='';task.error.value=''"/><el-form v-else label-position="top" @submit.prevent="task.run(login)"><el-form-item label="账号"><el-input v-model="username" autocomplete="username" aria-label="账号" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" autocomplete="current-password" aria-label="密码" show-password size="large"/></el-form-item><el-form-item label="验证器验证码（已启用时必填）"><el-input v-model="mfaCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" aria-label="管理员验证器验证码"/></el-form-item><el-button type="primary" native-type="submit" size="large" class="login-submit" :disabled="task.busy.value || !username || !password">登录管理端</el-button></el-form><el-button text @click="showMfaSetup=!showMfaSetup">首次设置管理员验证器</el-button><AdministratorMfaSetup v-if="showMfaSetup" :username="username" :password="password" @completed="mfaCompleted"/></div></div>
<div v-else class="layout admin-shell"><aside class="sidebar admin-sidebar"><RouterLink to="/" class="admin-brand"><img src="/brand-logo.png" alt="天机学堂"/><span>教学管理平台</span></RouterLink><nav><RouterLink v-if="session.role!==3" to="/" exact-active-class="selected">▦　数据看板</RouterLink><template v-if="session.role!==3"><section v-for="group in groups" :key="group.name" class="nav-group"><small>{{group.name}}</small><RouterLink v-for="key in group.keys" :key="key" :to="'/'+key" exact-active-class="selected">{{resources[key]!.title}}</RouterLink></section><RouterLink to="/role-permissions" exact-active-class="selected">角色权限绑定</RouterLink><RouterLink to="/privacy-requests" exact-active-class="selected">隐私权利申请</RouterLink></template><section class="nav-group"><small>{{session.role===3?"教学工作台":"教学与系统运维"}}</small><RouterLink to="/teaching" exact-active-class="selected">教学学情与答疑</RouterLink><RouterLink v-if="session.role!==3" to="/seasons" exact-active-class="selected">赛季与奖励</RouterLink><RouterLink to="/exams" exact-active-class="selected">试卷与评分</RouterLink><RouterLink v-if="session.role!==3" to="/reliability" exact-active-class="selected">失败与补偿任务</RouterLink><RouterLink v-if="session.role!==3" to="/audit" exact-active-class="selected">管理操作审计</RouterLink><RouterLink to="/operations" exact-active-class="selected">操作记录</RouterLink></section></nav></aside>
<main class="main admin-main"><header class="topbar"><div><small class="muted">天机学堂 / 管理工作台</small><p class="workspace-title">{{pageTitle}}</p></div><div class="header-actions"><span class="admin-role">{{session.role===3?'教师工作台':'管理工作台'}}</span><el-button text @click="task.run(()=>session.logout())">退出登录</el-button></div></header><Status :error="task.error.value || session.expiredMessage"/><EnvironmentBanner/><RouterView v-if="!teacherRestricted" :key="route.path"/><p v-else class="muted">正在打开教师工作台…</p></main></div></el-config-provider></template>
